function validate(input) {
  const [arr1, arr2] = input;
  for (const [name, arr] of [['arr1', arr1], ['arr2', arr2]]) {
    if (!Array.isArray(arr)) return `${name} must be an array of objects.`;
    if (JSON.stringify(arr).length > 100000) return `${name} is too large: keep its JSON text within 10^5 characters.`;
    const ids = new Set();
    for (const item of arr) {
      if (item === null || typeof item !== 'object' || Array.isArray(item)) return `Every element of ${name} must be an object.`;
      if (!Number.isInteger(item.id) || Math.abs(item.id) > 1e9) return `Every object in ${name} needs an integer id with |id| <= 10^9.`;
      if (ids.has(item.id)) return `The id ${item.id} appears twice in ${name}.`;
      ids.add(item.id);
    }
    const stack = [...arr];
    while (stack.length) {
      const value = stack.pop();
      if (value === null || typeof value !== 'object') continue;
      if (!Array.isArray(value) && Object.hasOwn(value, '__proto__')) return 'Keys named "__proto__" are not allowed.';
      for (const key of Object.keys(value)) stack.push(value[key]);
    }
  }
  return null;
}

