function join(arr1, arr2) {
  const ids = [];
  for (const item of arr1.concat(arr2)) {
    if (!ids.includes(item.id)) ids.push(item.id);
  }
  for (let i = 0; i < ids.length; i++) {
    for (let j = i + 1; j < ids.length; j++) {
      if (ids[j] < ids[i]) [ids[i], ids[j]] = [ids[j], ids[i]];
    }
  }
  return ids.map((id) => {
    const out = {};
    for (const source of [arr1.find((item) => item.id === id), arr2.find((item) => item.id === id)]) {
      if (!source) continue;
      for (const key of Object.keys(source)) out[key] = source[key];
    }
    return out;
  });
}

