function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const keys = small ? ['x', 'y', 'b', 'v'] : ['x', 'y', 'z', 'b', 'v', 'name', 'tag', 'n'];
  const primitive = () => {
    const roll = rand();
    if (roll < 0.5) return Math.floor(rand() * 21) - 5;
    if (roll < 0.7) return pick(['', 'a', 'b', 'cc']);
    if (roll < 0.85) return rand() < 0.5;
    return null;
  };
  const value = () => {
    const roll = rand();
    if (roll < 0.15) return Array.from({ length: Math.floor(rand() * 3) }, primitive);
    if (roll < 0.3) return { [pick(keys)]: primitive() };
    return primitive();
  };
  const span = small ? 8 : 3000, low = small ? -2 : -500;
  const build = (count) => {
    const used = new Set(), arr = [];
    while (arr.length < count) {
      const id = low + Math.floor(rand() * span);
      if (used.has(id)) continue;
      used.add(id);
      const item = { id };
      const fields = Math.floor(rand() * (small ? 3 : 4));
      for (let i = 0; i < fields; i++) item[pick(keys)] = value();
      arr.push(item);
    }
    return arr;
  };
  const size1 = small ? Math.floor(rand() * 5) : 600 + Math.floor(rand() * 400);
  const size2 = small ? Math.floor(rand() * 5) : 600 + Math.floor(rand() * 400);
  return [build(size1), build(size2)];
}
